    auto get_view() -> View {
        return {
            entity_indices,
            locations.get_view(),
            rotations.get_view(),
            teams,
            healths,
            laser_damages,
        };
    }
    auto get_view() const -> ConstView {
        return {
            entity_indices,
            locations.get_view(),
            rotations.get_view(),
            teams,
            healths,
            laser_damages,
        };
    }
